/// Scripts that emit typed events into the web view. Pass the result to runJavaScript.
abstract final class BridgeEvents {
  static String syncChanged({required List<String> buckets}) => eventScript('sync.changed', {'buckets': buckets});
  static String bundleUpdateReady({required int seq}) => eventScript('bundle.updateReady', {'seq': seq});
  static String appResumed() => eventScript('app.resumed', const <String, Object?>{});
  static String authExpired() => eventScript('auth.expired', const <String, Object?>{});
  static String syncDone({required SyncResult result}) => eventScript('sync.done', {'result': result.toJson()});
  static String appLifecycle({required String state}) => eventScript('app.lifecycle', {'state': state});
  static String appOnline({required bool online}) => eventScript('app.online', {'online': online});
  static String appAppearance({required bool darkMode, required bool highContrast, required bool reducedMotion}) => eventScript('app.appearance', {'darkMode': darkMode, 'highContrast': highContrast, 'reducedMotion': reducedMotion});
}

/// The built-in bridge methods, implemented against the `valence` runtime.
///
/// Extend it and implement your own methods; the built-ins are inherited. The bodies here are only
/// marshalling — every decision they make lives in the package, so a fix ships with an upgrade:
///
/// ```dart
/// class AppHandlers extends ValenceBuiltins implements BridgeHandlers {
///   AppHandlers(super.valence);
///
///   @override
///   Future<void> hapticsTap() async => HapticFeedback.lightImpact();
/// }
/// ```
abstract class ValenceBuiltins {
  /// Wraps an open runtime.
  ValenceBuiltins(this.valence);

  /// The runtime every built-in delegates to.
  final Valence valence;

  /// `app.ready`, from the package.
  Future<void> appReady() async {
    await valence.appReady();
  }

  /// `app.info`, from the package.
  Future<AppInfo> appInfo() async {
    final i = valence.appInfo();
    return AppInfo(platform: i.platform, host: i.host, bridge: i.bridge, bundle: i.bundle, locale: i.locale, fontScale: i.fontScale);
  }

  /// `data.get`, from the package.
  Future<Object?> dataGet(DataGetParams p) async {
    return valence.dataGet(p.bucket, p.key);
  }

  /// `data.list`, from the package.
  Future<List<Row>> dataList(DataListParams p) async {
    final rows = await valence.dataList(p.bucket, prefix: p.prefix, limit: p.limit, after: p.after);
    return [for (final r in rows) Row(key: r.key, value: r.value, usn: r.usn)];
  }

  /// `data.put`, from the package.
  Future<void> dataPut(DataPutParams p) async {
    await valence.dataPut(p.bucket, p.key, p.value);
  }

  /// `sync.now`, from the package.
  Future<SyncResult> syncNow(SyncNowParams p) async {
    final r = await valence.syncNow(buckets: p.buckets);
    return SyncResult(buckets: r.buckets, changed: r.changed, offline: r.offline, reason: r.reason.name, pending: r.pending);
  }

  /// `prefs.get`, from the package.
  Future<String?> prefsGet(PrefsGetParams p) async {
    return valence.prefsGet(p.key);
  }

  /// `prefs.set`, from the package.
  Future<void> prefsSet(PrefsSetParams p) async {
    await valence.prefsSet(p.key, p.value);
  }

  /// `open.external`, from the package.
  Future<void> openExternal(OpenExternalParams p) async {
    await valence.openExternal(p.url);
  }

  /// `bundle.applyUpdate`, from the package.
  Future<void> bundleApplyUpdate() async {
    await valence.applyUpdate();
  }

  /// `secure.get`, from the package.
  Future<String?> secureGet(SecureGetParams p) async {
    return valence.secureGet(p.key);
  }

  /// `secure.set`, from the package.
  Future<void> secureSet(SecureSetParams p) async {
    await valence.secureSet(p.key, p.value);
  }

  /// `secure.delete`, from the package.
  Future<void> secureDelete(SecureDeleteParams p) async {
    await valence.secureDelete(p.key);
